{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; Create or replace table snitch_db.maplemonk.overall_aging as wITH AGING AS ( WITH inward_batches AS ( SELECT \"Vendor SkuCode\" AS sku, \"Warehouse Name\" AS facility, DATE_TRUNC(\'Day\', \"PO Date\"::date) AS inward_date, \"Quantity Received\"::int AS batch_qty, DATEDIFF(DAY, DATE_TRUNC(\'Day\', \"GRN Date\"::date), CURRENT_DATE) AS batch_aging, row_number() over (partition by \"Vendor SkuCode\",\"Warehouse Name\" order by DATE_TRUNC(\'Day\', \"PO Date\"::date) desc ) rn FROM snitch_db.maplemonk.unicommerce_final_get_grn_report WHERE \"Warehouse Name\" IS NOT NULL and sku is not null and sku !=\'\' ORDER BY sku, facility, inward_date DESC ), live_inventory AS ( SELECT \"Item SkuCode\" AS sku, REVERSE(SUBSTRING(REVERSE(REPLACE(\"Item SkuCode\", \'\"\', \'\')), POSITION(\'-\' IN REVERSE(REPLACE(\"Item SkuCode\", \'\"\', \'\'))) + 1)) AS sku_group, FACILITY, SUM( COALESCE(TRY_CAST(CAST(inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND CAST(facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\',\'SAPL-SR\') GROUP BY \"Item SkuCode\", sku_group, FACILITY HAVING SUM( COALESCE(TRY_CAST(CAST(inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putback Pending\" AS STRING) AS FLOAT), 0) ) >0 ), cumulative_inward AS ( SELECT sku, facility, inward_date, batch_qty, batch_aging, SUM(batch_qty) OVER (PARTITION BY sku, facility ORDER BY inward_date DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_qty FROM inward_batches ), deduplicated_matches AS ( SELECT ci.sku, ci.facility, ci.inward_date, ci.batch_qty, ci.batch_aging, ci.cum_qty, li.units_on_hand, CASE WHEN ci.cum_qty - ci.batch_qty >= li.units_on_hand THEN 0 WHEN ci.cum_qty > li.units_on_hand THEN li.units_on_hand - (ci.cum_qty - ci.batch_qty) ELSE ci.batch_qty END AS matched_qty FROM cumulative_inward ci LEFT JOIN live_inventory li ON ci.sku = li.sku AND ci.facility = li.facility ), final_aging AS ( SELECT sku, facility, ROUND(SUM(batch_aging * matched_qty) / NULLIF(SUM(matched_qty), 0), 2) AS weighted_aging, SUM(matched_qty) AS total_inventory FROM deduplicated_matches WHERE matched_qty > 0 GROUP BY sku, facility ) SELECT * FROM final_aging ), LIVE AS (SELECT \"Item SkuCode\" AS sku, REVERSE(SUBSTRING(REVERSE(REPLACE(\"Item SkuCode\", \'\"\', \'\')), POSITION(\'-\' IN REVERSE(REPLACE(\"Item SkuCode\", \'\"\', \'\'))) + 1)) AS sku_group, FACILITY, SUM( COALESCE(TRY_CAST(CAST(inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand, \"Item Type Name\" AS PRODUCT_NAME, \"Category Name\" AS CATEGORY, CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' ELSE size END AS size_mapped, size FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND CAST(facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\',\'SAPL-SR\') GROUP BY \"Item SkuCode\", sku_group, \"Item Type Name\", \"Category Name\", size, FACILITY HAVING SUM( COALESCE(TRY_CAST(CAST(inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(\"Putback Pending\" AS STRING) AS FLOAT), 0) ) >0 ), CLASS AS ( Select * from ( Select sku_group, sku_class,final_ros,natural_ros, row_number() over (partition by sku_group order by 1 desc ) as rn from snitch_db.maplemonk.availability_master_v2) where rn =1 ) Select a.*, b.WEIGHTED_AGING as \"Days in warehouse\", CASE WHEN b.WEIGHTED_AGING is null then null WHEN b.WEIGHTED_AGING < 30 THEN \'0-30\' WHEN b.WEIGHTED_AGING >= 30 AND b.WEIGHTED_AGING < 60 THEN \'30-60\' WHEN b.WEIGHTED_AGING >= 60 AND b.WEIGHTED_AGING < 90 THEN \'60-90\' WHEN b.WEIGHTED_AGING >= 90 AND b.WEIGHTED_AGING < 120 THEN \'90-120\' WHEN b.WEIGHTED_AGING >= 120 AND b.WEIGHTED_AGING < 150 THEN \'120-150\' WHEN b.WEIGHTED_AGING >= 150 AND b.WEIGHTED_AGING < 180 THEN \'150-180\' WHEN b.WEIGHTED_AGING >= 180 AND b.WEIGHTED_AGING < 210 THEN \'180-210\' WHEN b.WEIGHTED_AGING >= 210 AND b.WEIGHTED_AGING < 240 THEN \'210-240\' WHEN b.WEIGHTED_AGING >= 240 AND b.WEIGHTED_AGING < 270 THEN \'240-270\' WHEN b.WEIGHTED_AGING >= 270 AND b.WEIGHTED_AGING < 300 THEN \'270-300\' WHEN b.WEIGHTED_AGING >= 300 AND b.WEIGHTED_AGING < 330 THEN \'300-330\' WHEN b.WEIGHTED_AGING >= 330 AND b.WEIGHTED_AGING < 360 THEN \'330-360\' ELSE \'> 360\' END AS days_in_warehouse_range, c.sku_class, c.sku_class as FINAL_SKU_CLASS, c.natural_ros, c.final_ros from LIVE a left join AGING b on a.sku =b.sku and a.FACILITY =b.FACILITY left join class c on a.sku_group = c.sku_group; create or replace table snitch_db.maplemonk.Inwards as WITH DerivedTable AS ( SELECT CASE WHEN RIGHT(a.\"Item Type skuCode\", 2) = \'-S\' THEN LEFT(a.\"Item Type skuCode\", LEN(a.\"Item Type skuCode\") - 2) ELSE REPLACE(a.\"Item Type skuCode\", CONCAT(\'-\', SPLIT_PART(a.\"Item Type skuCode\", \'-\', -1)), \'\') END AS sku_group, LEFT(a.\"UPDATED\", 10)::DATE AS date, \"Warehouse Name\" as warehouse_name, SUM( case when type = \'PUTAWAY_GRN_ITEM\' and lower(a.\"Created By\") not like \'%storereturns%\' then a.\"Putaway Completed Quantity\" else 0 end) AS Inwared_quantity, SUM( case when type in (\'PUTAWAY_RECEIVED_RETURNS\',\'PUTAWAY_REVERSE_PICKUP_ITEM\',\'PUTAWAY_COURIER_RETURNED_ITEMS\') or lower(a.\"Created By\") like \'%storereturns%\' then a.\"Putaway Completed Quantity\" else 0 end) AS Return_quantity, a.category FROM snitch_db.maplemonk.snitch_final_get_put_away_new a group by 1,2,3, a.category ) SELECT dt.sku_group, dt.date, dt.Inwared_quantity, dt.Return_quantity, dt.warehouse_name, dt.category, case when b.sku_class is null then \'4-New\' else b.sku_class end Sku_class, b.final_ros, b.product_name FROM DerivedTable dt LEFT JOIN snitch_db.maplemonk.availability_master_v2 b ON dt.sku_group = b.sku_group; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.liquidation_list AS SELECT ia.SKU, ia.SKU_GROUP, ia.PRODUCT_NAME, ia.DAYS_IN_WAREHOUSE_RANGE, SUM(ia.UNITS_ON_HAND) AS TOTAL_UNITS_ON_HAND, ia.CATEGORY, ia.size_mapped, ia.facility, ol.Last_7_days_sales, r.FINAL_ROS FROM ( SELECT SKU, SKU_GROUP, PRODUCT_NAME, DAYS_IN_WAREHOUSE_RANGE, SUM(UNITS_ON_HAND) AS UNITS_ON_HAND, CATEGORY, facility, size_mapped, FROM Snitch_db.maplemonk.overall_aging WHERE DAYS_IN_WAREHOUSE_RANGE NOT IN (\'61-90\', \'91-120\', \'31-60\', \'0-30\') GROUP BY SKU, SKU_GROUP, PRODUCT_NAME, DAYS_IN_WAREHOUSE_RANGE, CATEGORY, facility, size_mapped ) AS ia LEFT JOIN ( SELECT SKU, SKU_GROUP, AVG(SHIPPING_QUANTITY) AS Last_7_days_sales FROM snitch_db.snitch.order_lineitems_fact WHERE order_date::date > (SELECT MAX(order_date::date) FROM snitch_db.snitch.order_lineitems_fact) - 7 GROUP BY SKU, SKU_GROUP ) AS ol ON ia.SKU = ol.SKU AND ia.SKU_GROUP = ol.SKU_GROUP LEFT JOIN ( SELECT SKU_GROUP, FINAL_ROS FROM SNITCH_DB.MAPLEMONK.ros_snitch ) AS r ON ia.SKU_GROUP = r.SKU_GROUP GROUP BY ia.SKU, ia.SKU_GROUP, ia.PRODUCT_NAME, ia.DAYS_IN_WAREHOUSE_RANGE, ia.CATEGORY, ia.size_mapped, ia.facility, ol.Last_7_days_sales, r.FINAL_ROS ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.Outward_Inward_Difference AS SELECT A.DISPATCH_DATE, A.WAREHOUSE_NAME, COALESCE(A.OUTWARD_QUANTITY, 0) AS OUTWARD_QUANTITY, COALESCE(B.INWARD_QUANTITY, 0) AS INWARD_QUANTITY, CASE WHEN B.INWARD_QUANTITY = 0 THEN 0 WHEN B.INWARD_QUANTITY < 10 THEN 0 ELSE COALESCE(((B.INWARD_QUANTITY - A.OUTWARD_QUANTITY) / B.INWARD_QUANTITY) * 100, 0) END AS PERCENTAGE_DIFFERENCE FROM ( SELECT DISPATCH_DATE, WAREHOUSE_NAME, SUM(SHIPPING_QUANTITY) AS OUTWARD_QUANTITY FROM SNITCH_DB.MAPLEMONK.Outward_class_warehouse WHERE DISPATCH_DATE IS NOT NULL AND ORDER_STATUS=\'COMPLETE\' GROUP BY DISPATCH_DATE, WAREHOUSE_NAME ) AS A LEFT JOIN ( SELECT DATE, WAREHOUSE_NAME, SUM(QUANTITY) AS INWARD_QUANTITY FROM SNITCH_DB.maplemonk.sku_class_mapping GROUP BY DATE, WAREHOUSE_NAME ) AS B ON A.DISPATCH_DATE = B.DATE AND A.WAREHOUSE_NAME = B.WAREHOUSE_NAME ORDER BY A.DISPATCH_DATE DESC; create or replace table snitch_db.maplemonk.P90 AS select PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY DATEDIFF(\'day\', order_date, delivered_date)) AS p90_days_to_delivery_order, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY DATEDIFF(\'day\', dispatch_date, delivered_date)) AS p90_days_to_delivery_dispatch, warehouse_name, ZONE from( select b.*, a.zone FROM snitch_db.maplemonk.unicommerce_fact_items_snitch b left join (select zone,delivery_state,city_tier,delivery_postcode from( select *, ROW_NUMBER() OVER (PARTITION BY DELIVERY_POSTCODE ORDER BY 1) RN from snitch_db.maplemonk.pincodemappingzoneupdatedsnitch) where rn=1) a on b.pincode =a.DELIVERY_POSTCODE) WHERE lower(marketplace_mapped) = \'shopify\' AND order_status = \'COMPLETE\' GROUP BY warehouse_name, Zone; Create or replace Table snitch_db.maplemonk.Shipment_ratio AS SELECT DISTINCT QTY , COUNT (AWB) as Total_Shipments FROM ( SELECT DISTINCT AWB, SUM(SHIPPING_QUANTITY) AS qty, FROM snitch_db.maplemonk.UNICOMMERCE_FACT_ITEMS_SNITCH WHERE ORDER_STATUS = \'COMPLETE\' AND MARKETPLACE_MAPPED = \'SHOPIFY\' and order_date >= getdate()::date - 30 and awb is not null GROUP BY 1 ) GROUP BY 1 ORDER BY QTY DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            